import type { APIRoute } from "astro";
import { getCollection } from "astro:content";
import { buildResourcesFeed, FEED_PATH } from "../lib/resources-feed";
import { SITE_URL } from "../lib/seo";

/**
 * GET /resources.json — the public, machine-readable index of every resource.
 *
 * Built at build time (static output), so the file is a real file on GitHub
 * Pages: no server, no cache to invalidate, and it is regenerated by the same
 * `npm run build` that publishes the pages it lists. Billy, 2026-10-21: external
 * agents and programs should be able to read what is available, newest first,
 * with both editions' titles and URLs and the hero image.
 *
 * Resources only — `type: "post"` is filtered out here as well as in the
 * builder, because "I only want resources" is a property of the feed, not of
 * one call site.
 *
 * Discovery, so the file is not a secret nobody links to:
 *   - `<link rel="alternate" type="application/json" href="/resources.json">`
 *     in every page's <head> (src/layouts/Base.astro)
 *   - a "Machine-readable index" section in /llms.txt (scripts/gen-llms-txt.mjs)
 *
 * The shape is documented in `public/resources.schema.json`, which the payload
 * names in its `$schema` field; `scripts/check-resources-feed.mjs` validates the
 * built file and `tests/resources-feed.test.ts` pins the rules (pairing, order,
 * dates, hero URLs).
 */
export const GET: APIRoute = async ({ site }) => {
  const entries = await getCollection("content", ({ data }) => data.type === "resource");
  const feed = buildResourcesFeed(entries, { site: (site ?? new URL(SITE_URL)).origin });

  return new Response(`${JSON.stringify(feed, null, 2)}\n`, {
    headers: {
      "content-type": "application/json; charset=utf-8",
      // Short cache: a published resource should appear in the feed within
      // minutes, and GitHub Pages serves a fresh copy after each deploy anyway.
      "cache-control": "public, max-age=600",
    },
  });
};

/** The built file is `dist/resources.json` — asserted by the feed gate. */
export const prerender = true;
export const PATH = FEED_PATH;
